const char* const s_hlslCommon =
    "// Generated by CGxDeviceD3d11 from the client's DX9 shader bytecode or its fixed-function state.\n"
    "struct GxVaryings {\n"
    "    float4 pos : SV_Position;\n"
    "    float4 c0 : COLOR0;\n"
    "    float4 c1 : COLOR1;\n"
    "    float4 t0 : TEXCOORD0;\n"
    "    float4 t1 : TEXCOORD1;\n"
    "    float4 t2 : TEXCOORD2;\n"
    "    float4 t3 : TEXCOORD3;\n"
    "    float4 t4 : TEXCOORD4;\n"
    "    float4 t5 : TEXCOORD5;\n"
    "    float4 t6 : TEXCOORD6;\n"
    "    float4 t7 : TEXCOORD7;\n"
    "    float4 t8 : TEXCOORD8;\n"
    "    float4 t9 : TEXCOORD9;\n"
    "    float4 n0 : NORMAL0;\n"
    "    float4 tg0 : TANGENT0;\n"
    "    float4 bn0 : BINORMAL0;\n"
    "    float fog : FOG;\n"
    "    float psize : PSIZE;\n"
    "    float4 clip0 : SV_ClipDistance0;\n"
    "    float2 clip1 : SV_ClipDistance1;\n"
    "};\n"
    "\n"
    "cbuffer GxDraw : register(b1) {\n"
    "    float4 gxViewport;       // x 1 / width, y 1 / height, z width, w height (pixels)\n"
    "    float4 gxClipPlanes[6];  // clip space for a vertex shader, world space for the fixed function\n"
    "    float4 gxAlphaTest;      // x reference / 255, y 1 = on (GREATEREQUAL)\n"
    "    float4 gxFog;            // rgb colour, a 1 = the fixed-function fog blend is on\n"
    "    float4 gxPointSize;      // x D3DRS_POINTSIZE, y min, z max, w 1 = sprite texture coordinates\n"
    "    float4 gxPointScale;     // xyz distance attenuation, w 1 = scaled\n"
    "    uint4 gxClipMask;        // x planes on\n"
    "};\n"
    "\n"
    "float4 Dx9Lit(float4 s) {\n"
    "    float4 d = float4(1.0, 0.0, 0.0, 1.0);\n"
    "    if (s.x > 0.0) {\n"
    "        d.y = s.x;\n"
    "        if (s.y > 0.0) {\n"
    "            d.z = pow(s.y, clamp(s.w, -128.0, 128.0));\n"
    "        }\n"
    "    }\n"
    "    return d;\n"
    "}\n"
    "\n"
    "float Dx9Pow(float x, float y) {\n"
    "    return x == 0.0 ? 0.0 : exp2(y * log2(abs(x)));\n"
    "}\n"
    "\n"
    "float4 Dx9Nrm(float4 v) {\n"
    "    return v * rsqrt(dot(v.xyz, v.xyz));\n"
    "}\n"
    "\n"
    "// the clip planes, and D3D9's rasterisation: D3D9 samples a pixel at its whole coordinate, D3D10 and later at its\n"
    "// centre, so the vertex moves half a pixel right and down and covers the pixels D3D9 would\n"
    "void GxFinishVertex(inout GxVaryings o, float4 p) {\n"
    "    uint m = gxClipMask.x;\n"
    "    o.clip0.x = (m & 1u) ? dot(p, gxClipPlanes[0]) : 1.0;\n"
    "    o.clip0.y = (m & 2u) ? dot(p, gxClipPlanes[1]) : 1.0;\n"
    "    o.clip0.z = (m & 4u) ? dot(p, gxClipPlanes[2]) : 1.0;\n"
    "    o.clip0.w = (m & 8u) ? dot(p, gxClipPlanes[3]) : 1.0;\n"
    "    o.clip1.x = (m & 16u) ? dot(p, gxClipPlanes[4]) : 1.0;\n"
    "    o.clip1.y = (m & 32u) ? dot(p, gxClipPlanes[5]) : 1.0;\n"
    "    o.pos.xy += float2(gxViewport.x, -gxViewport.y) * o.pos.w;\n"
    "}\n"
    "\n"
    "void GxAlphaTest(float a) {\n"
    "    if (gxAlphaTest.y > 0.0 && a < gxAlphaTest.x) {\n"
    "        discard;\n"
    "    }\n"
    "}\n"
    "\n"
    "float3 GxFogBlend(float3 c, float f) {\n"
    "    return gxFog.a > 0.0 ? lerp(gxFog.rgb, c, saturate(f)) : c;\n"
    "}\n"
    "\n";

